// Offset floating texts so consecutive pickups never overlap each other or the player nametag
function spawnFloatText(st, x, y, text, color, life = 0.85) {
  let targetX = x;
  let targetY = y;
  if (Math.abs(targetX - PLAYER_SCREEN_X) < 40 && targetY > st.py - 84) {
    targetY = st.py - 84;
  }
  let shiftCount = 0;
  for (const f of st.floatTexts) {
    if (Math.abs(f.x - targetX) < 75 && Math.abs(f.y - targetY) < 22) {
      targetY -= 20;
      shiftCount++;
    }
  }
  if (shiftCount > 0) {
    targetX += ((shiftCount % 3) - 1) * 16;
  }
  st.floatTexts.push({ x: targetX, y: targetY, text, color, life });
}

// Apply damage to OVER-1 in Action Stage (drops 2 of 28 HP segments, resets charge aura, electric shock flinch)
function damagePlayerInStage(st, game, source) {
  const twoSegDmg = Math.max(1, Math.round(st.maxHp * (2 / 28)));
  st.hp = Math.max(1, st.hp - twoSegDmg);
  st.hurtTimer = 0.75;
  st.chargeTime = 0;
  st.chargeTier = 0;
  st.comboCount = 0;
  game.triggerShake(6, 0.22);
  Sound.SFX.hit(1);
  spawnFloatText(st, PLAYER_SCREEN_X, st.py - 88, `-${twoSegDmg} HP`, "#fb7185", 0.9);
  for (let i = 0; i < 8; i++) {
    const ang = (Math.PI * 2 * i) / 8;
    st.particles.push({
      x: PLAYER_SCREEN_X,
      y: st.py - 28,
      vx: Math.cos(ang) * 110,
      vy: Math.sin(ang) * 110,
      life: 0.32,
      maxLife: 0.32,
      color: i % 2 === 0 ? "#facc15" : "#ffffff",
      size: 5,
    });
  }
  game.pushEvent("hit", { source, hp: st.hp, maxHp: st.maxHp });
}

// Spawn a co-op projectile from a connected room squadmate
function spawnCoopAllyShot(st, game, opts = {}) {
  if (!st || st.cleared) return;
  const tier = opts.tier || 1;
  const colors = ["#38bdf8", "#60a5fa", "#facc15", "#fb7185"];
  const sizes = [8, 11, 15, 20];
  const allyY = typeof opts.y === "number" ? Math.min(GROUND_Y, Math.max(220, opts.y)) : GROUND_Y;
  st.bullets.push({
    x: (opts.x || PLAYER_SCREEN_X - 42) + 22,
    y: allyY - 32,
    vx: 780,
    tier,
    pierceLeft: tier >= 2 ? 2 : 1,
    maxPierce: tier >= 2 ? 2 : 1,
    killsThisShot: 0,
    color: colors[tier] || "#60a5fa",
    radius: sizes[tier] || 10,
    fromAlly: opts.fromName || "ALLY",
    trail: [],
  });
}

