// Rule 7: Giga Crush leaps into the air and blasts 6 circular explosions in a 3x2 grid with 1Hit!!..6Hit!! popups
function triggerGigaCrush(st, game) {
  if (st.cleared || st.warpTimer > 0) return;
  if (st.gigaGauge < st.gigaMax || st.gigaActiveTimer > 0) return;

  st.gigaGauge = 0;
  st.gigaActiveTimer = 1.15;
  st.vy = -320;
  st.py = Math.min(st.py, GROUND_Y - 120);
  game.triggerShake(12, 0.55);
  Sound.SFX.gigaCrush();
  showStageBanner(st, "GIGA CRUSH!! FULL SCREEN BLAST!", "gold");

  // 3 columns x 2 rows circular energy explosions with 1Hit!!..6Hit!! popups (Footage A 01:17-01:19)
  st.gigaBeams = [];
  const cols = [440, 740, 1040];
  const rows = [245, 455];
  let hitNum = 1;
  for (let r = 0; r < rows.length; r++) {
    for (let c = 0; c < cols.length; c++) {
      st.gigaBeams.push({
        screenX: cols[c],
        screenY: rows[r],
        hitNum: hitNum++,
        delay: (r * 3 + c) * 0.045,
        timer: 0.95,
        maxTimer: 0.95,
        color: (r + c) % 2 === 0 ? "#facc15" : "#fb923c",
      });
    }
  }

  // Clear all enemy bullets & visible enemies on screen
  st.enemyBullets = [];
  let destroyed = 0;
  for (const e of st.enemies) {
    const sx = e.x - st.scrollX;
    if (e.alive && sx > -40 && sx < 1320) {
      defeatEnemy(st, game, e, true);
      destroyed++;
    }
  }
  game.pushEvent("item_use", { item: "giga_crush", destroyed });
}
